07_cta_principal_invalido":true,"s22t07_cta_home_o_reabre_pago":true,"s22t07_destino_no_canonico":true,"s22t07_gestion_plan_no_activado":true},"esperado":false}]},"hash":"a7ac7abbae21e1a22aff93760cab9cfe890d143f72d013d6145eaf3d7d13c760","hash_evaluado":"a7ac7abbae","hash_paquete":"405ad57b8523875fd05869b6151158d9ad61c5c934730830bd6dab3c6aae93dc","hash_paquete_10":"405ad57b85"},{"codigo":"S22T-C08","legacy_id":332,"legacy_ids":[332],"relacionadas":["S22O-C02"],"residual":"","coberturas":[{"legacy_id":332,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En notificación de éxito de cuotas BLOQUEAR envío de confirmación de activación sin PAYMENT_CONFIRMED y activación real del plan. Canal whatsapp con template_meta UTILITY autorizado; contenido confirmacion_plan_activado, numero_operacion, monto_pagado y link_documentos desde fuentes backend; link solo documentos elegibles y acceso autorizado, no prometer carta antes de SETTLED_CONFIRMED/AVAILABLE. Envío automático tras pago confirmado y plan activado, sin convertir notificación en autoridad de estado. No enviar ni activar canal en esta migración; binding pendiente."}],"hechos":["s22t08_evalua_notificacion_exito_cuotas","s22t08_pago_o_plan_no_confirmado","s22t08_canal_o_template_no_autorizado","s22t08_contenido_incompleto_o_no_autoritativo","s22t08_link_documento_no_elegible","s22t08_notificacion_como_autoridad"],"paquete":{"tipo":"NUEVA","codigo":"S22T-C08","clave":"s22t_legacy_332","familia":"NOTIFICATIONS_DELIVERY","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Confirmación operativa de plan por WhatsApp","descripcion":"En notificación de éxito de cuotas BLOQUEAR envío de confirmación de activación sin PAYMENT_CONFIRMED y activación real del plan. Canal whatsapp con template_meta UTILITY autorizado; contenido confirmacion_plan_activado, numero_operacion, monto_pagado y link_documentos desde fuentes backend; link solo documentos elegibles y acceso autorizado, no prometer carta antes de SETTLED_CONFIRMED/AVAILABLE. Envío automático tras pago confirmado y plan activado, sin convertir notificación en autoridad de estado. No enviar ni activar canal en esta migración; binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/332","solicitante":"Cristhian / Claude S22-T 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22t08_evalua_notificacion_exito_cuotas"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22t08_pago_o_plan_no_confirmado"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22t08_canal_o_template_no_autorizado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22t08_contenido_incompleto_o_no_autoritativo"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22t08_link_documento_no_elegible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22t08_notificacion_como_autoridad"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":false,"s22t08_canal_o_template_no_autorizado":false,"s22t08_contenido_incompleto_o_no_autoritativo":false,"s22t08_link_documento_no_elegible":false,"s22t08_notificacion_como_autoridad":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":true,"s22t08_canal_o_template_no_autorizado":false,"s22t08_contenido_incompleto_o_no_autoritativo":false,"s22t08_link_documento_no_elegible":false,"s22t08_notificacion_como_autoridad":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":false,"s22t08_canal_o_template_no_autorizado":true,"s22t08_contenido_incompleto_o_no_autoritativo":false,"s22t08_link_documento_no_elegible":false,"s22t08_notificacion_como_autoridad":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":false,"s22t08_canal_o_template_no_autorizado":false,"s22t08_contenido_incompleto_o_no_autoritativo":true,"s22t08_link_documento_no_elegible":false,"s22t08_notificacion_como_autoridad":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":false,"s22t08_canal_o_template_no_autorizado":false,"s22t08_contenido_incompleto_o_no_autoritativo":false,"s22t08_link_documento_no_elegible":true,"s22t08_notificacion_como_autoridad":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":true,"s22t08_pago_o_plan_no_confirmado":false,"s22t08_canal_o_template_no_autorizado":false,"s22t08_contenido_incompleto_o_no_autoritativo":false,"s22t08_link_documento_no_elegible":false,"s22t08_notificacion_como_autoridad":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22t08_evalua_notificacion_exito_cuotas":false,"s22t08_pago_o_plan_no_confirmado":true,"s22t08_canal_o_template_no_autorizado":true,"s22t08_contenido_incompleto_o_no_autoritativo":true,"s22t08_link_documento_no_elegible":true,"s22t08_notificacion_como_autoridad":true},"esperado":false}]},"hash":"18e2ca16e204681a74c86a6fc8183f3801005b0b08e05d8ae78ec56865600923","hash_evaluado":"18e2ca16e2","hash_paquete":"a2aa238ab7ee141db4f025da76306648d081ca619b22824cce0e4bf127e7c848","hash_paquete_10":"a2aa238ab7"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>8 OR vectors<>47 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22T proposal-only: independent judgment pending';
END $s22$;
COMMIT;
